/**
 * The pupil's ladder for a past paper question: what it asks, how the marks go,
 * then two to four moves with this question's own working beside them.
 *
 * **Generated — do not edit.** Run \`npx tsx scripts/emit-paper-plan.ts\`, and
 * \`__checks__/plans.ts\` judges what goes into it.
 *
 * \`PLANS\` is keyed by variation, because the method is shared by every paper
 * question modelled on it. \`PLAN_OF\` is keyed by paper label, because the mark
 * split and the working are that question's own.
 *
 * A \`shows\` entry is null where the working is withheld — the last row of a
 * question is its answer, and so are 52 mid-rows besides.
 *
 * Contains information reproduced from Qualifications Scotland marking
 * instructions, with permission, and with Qualifications Scotland acknowledged
 * as the source.
 *
 * No imports, deliberately: a pupil asking for a hint should not download the
 * 33,000-line engine to read one line of text.
 */
export interface Plan {
  /** What the question is asking the pupil to do. */
  skill: string;
  /** How the marks go, in one line. */
  method: string;
  /** Two to four moves, in the order they are done. */
  moves: string[];
}
export interface PlanOf {
  /** The variation whose plan this question is shown. */
  v: string;
  /** What each move is worth on THIS question. A 0 shows no chip at all. */
  marks: number[];
  /** This question's working as each move begins, or null where it is withheld. */
  shows: (string | null)[];
}

/** One payload per exam-tier variation. */
export const PLANS: Record<string, Plan> = {
  "fractions.multiply-mixed": {"skill":"Multiply a mixed number by a fraction or another mixed number","method":"Turn both mixed numbers into improper fractions and multiply them, then tidy the answer up","moves":["Turn each mixed number into a top-heavy fraction so there is no whole number left sitting outside a fraction line — whole numbers and fractions cannot be multiplied while they are separated like that","Multiply the two tops together and the two bottoms together, then cancel the result down and write it as a mixed number if the top ends up bigger than the bottom"]},
  "expanding.two-binomials": {"skill":"Multiply every term in one bracket by every term in the other","method":"Any three terms correct, then the fourth term and the like terms collected","moves":["Take the first term of the left bracket across both terms of the right, then the second term across both, keeping each sign attached to the number in front of it, so you finish with four products in a row","Two of those four are terms in \\(x\\), so add their coefficients and write your answer as a squared term, a single \\(x\\) term and a number"]},
  "quadratics.complete-square": {"skill":"Write \\(x^2+bx+c\\) in the form \\((x+p)^2+q\\)","method":"Halve the coefficient of \\(x\\) to get the number inside the bracket, then take off what that bracket adds on and bring the constant down","moves":["Halve the coefficient of \\(x\\). That number goes inside the bracket, and the bracket is squared","Expanding that bracket would add an extra term, so subtract it again and bring the constant down beside it"]},
  "vectors.components": {"skill":"Scale two vectors and combine them, answering in component form","method":"Multiply each component by its scalar, then add the two vectors one component at a time","moves":["Multiply every component of a vector by the number sitting in front of it, doing each vector in turn","Combine the two results one component at a time, keeping the plus or minus that sits between them"]},
  "sine-rule.side-exact": {"skill":"Pair each side with its opposite angle, then multiply up","method":"Pair each side with the angle opposite it and substitute into the sine rule, multiply up to make the side the subject, then work it out","moves":["Work out which angle faces the side you are chasing and which faces the side you already know, then write each of those sides over the sine of the angle facing it and set the two fractions equal","Multiply both sides by the sine sitting underneath the missing length, so that length is on its own","Work the resulting fraction out and write the length down with its units"]},
  "straight-line.best-fit": {"skill":"Read two points off a graph, find the equation, then use it","method":"Read two points off your line and find the gradient, substitute it with one of the points to get the intercept, write the equation in the letters the question uses, then put the given value into it","moves":["Pick the two marked points on the line of best fit and work out the change up divided by the change across, which gives you the gradient","Put that gradient and one of those two points into \\(y = mx + c\\), so that \\(c\\) is the only thing left unknown","Work \\(c\\) out, then write the equation using the question's own letters instead of \\(x\\) and \\(y\\)","Put the value given in the second part into your equation to get the quantity it asks for"]},
  "quadratics.parabola-scale": {"skill":"Substitute a point on a parabola to find its stretch","method":"Know to substitute the marked point into \\(y = ax^2\\), then solve for \\(a\\)","moves":["Read the marked point's coordinates off the diagram and put them in place of \\(x\\) and \\(y\\) in \\(y = ax^{2}\\), since the point lies on the curve","Work out the square, then divide to leave \\(a\\) on its own"]},
  "surds.sum-three": {"skill":"Reduce three surds to a common root, then add the coefficients","method":"Take the largest square factor out of the first surd, do the same to the third, then add the coefficients of the matching roots","moves":["Split the first root into its largest square factor times what is left, and bring the root of that square factor out in front","Do the same to the other root that is not yet in its simplest form","All three terms now sit on the same root, so add the coefficients together and keep that root beside the total"]},
  "percentages.part-of-whole": {"skill":"Recover a total when a part is given as a straight percentage of it","method":"The amount you are given is that percentage of the total, so divide to find 1%, then multiply by 100","moves":["Write down what you are told: that percentage of the total is the amount given","Divide by that percentage to find what 1% is worth","Multiply by 100 to get the whole"]},
  "trig-graphs.shift": {"skill":"Read an amplitude and a phase shift off a trigonometric graph","method":"State a, the amplitude, then state b from how far the graph has moved sideways","moves":["Read off the \\(y\\)-axis how far the curve reaches above the \\(x\\)-axis at the peak — that distance from the middle to the top gives \\(a\\)","Find where the peak sits along the \\(x\\)-axis. An unshifted \\(\\cos\\) graph peaks at \\(x = 0\\) and an unshifted \\(\\sin\\) graph climbs through \\(0\\), so the gap between that and the graph in front of you is how far the wave has slid — a slide to the right means a minus sign inside the bracket"]},
  "straight-line.gradient-and-x-intercept": {"skill":"Rearrange for the gradient, then find where the line meets the x-axis","method":"Start the rearrangement and state the gradient, then set y = 0 and state the intercept as coordinates","moves":["Get the term in \\(y\\) by itself on one side, moving the \\(x\\) term and the number across","Divide every term by the number in front of \\(y\\), and whatever multiplies \\(x\\) is the gradient","For the second part go back to the original equation and replace \\(y\\) with 0, since the line has no height where it meets the \\(x\\)-axis","Solve that for \\(x\\) and write the crossing point as coordinates in brackets, with 0 as the second number"]},
  "pythagoras.chord": {"skill":"Drop a perpendicular to the chord, use Pythagoras, add or subtract the radius","method":"Drop a perpendicular from the centre to the chord to make a right-angled triangle, write Pythagoras down for it, work out the third side, then add or subtract the radius","moves":["Halve the chord, because the perpendicular dropped from the centre lands on its midpoint and makes a right-angled triangle","Write Pythagoras down for that triangle, with the radius as the hypotenuse and half the chord as one of the short sides","Take the square root to get the distance from the centre to the chord","Add that distance to the radius, or take it off, depending on whether the piece you want is the bigger one or the smaller one"]},
  "quadratics.reaches-height": {"skill":"Solve a quadratic model for a stated height, then decide whether a greater height is reached","method":"Construct the equation, rearrange to zero, factorise and select the first of the two times; then the turning point, the maximum height, and a conclusion comparing it with the height asked about","moves":["Set the height formula equal to the height in the question, then gather every term on one side so the quadratic equals zero","Factorise that quadratic into two brackets","Set each bracket to zero for the two times, and pick the earlier one — the object passes that height on the way up and again on the way down","For the second part take the time halfway between those two, work out the height at that moment, and compare it with the height you are asked about before answering"]},
  "percentages.compound": {"skill":"Apply a multiplier once per year, then round as the question asks","method":"Know how to change by the rate, then know how to carry it across the years, then evaluate to the stated accuracy","moves":["Turn the percentage change into a multiplier","Raise that multiplier to the number of years, and multiply the starting amount by it","Work it out, rounding to whatever accuracy the question asks for"]},
  "coords.cube-on-cuboid": {"skill":"Read a coordinate off a solid standing on another","method":"State one coordinate, state the other","moves":["Work out the cube's edge length from the solid beneath it, since it sits exactly across the top and all a cube's edges match","For the point directly above the labelled one, keep its \\(x\\) and \\(y\\) and add the cube's edge to its height","For the far top corner, step the cube's edge along \\(x\\) and along \\(y\\) from that point, checking against the diagram which way each step goes before writing it down"]},
  "simeq.construct-solve": {"skill":"Build both equations from a context, solve, answer in units","method":"Write an equation for each situation, multiply one of them so a letter matches, eliminate that letter for the first value, substitute back for the second, then give both answers in their units","moves":["Give each of the two unknown amounts a letter and say what it stands for, then turn the first sentence into an equation: how many of each, multiplied by its letter, adding up to the total that sentence gives","Do the same with the second sentence, so you have two equations sharing the same two letters","Multiply one equation right through so one letter matches in both, then add or subtract to cancel that letter and work out the one left behind","Put that back into either of your own equations for the other letter, then finish with a sentence naming both amounts in the units the question uses, because that wording carries a mark of its own"]},
  "data.mean-sd-consistency": {"skill":"Find the mean and standard deviation, then judge consistency from the deviation alone","method":"The mean is its own part, then the squared differences, the formula and the standard deviation, then a single judgement","moves":["Add all the values and divide by how many there are to get the mean \\(\\bar{x}\\)","Subtract the mean from each value, square every one of those differences, and add them for \\(\\sum(x - \\bar{x})^{2}\\)","Put that total into \\(s = \\sqrt{\\frac{\\sum(x - \\bar{x})^{2}}{n - 1}}\\), where the top collects the squared differences and the bottom is one less than the number of values, then take the root","Answer the last part from the standard deviations alone, saying what the size of each one tells you about how spread out that sample's values are, because the means say nothing about spread"]},
  "similarity.volume-scale": {"skill":"Cube the linear scale factor to scale a volume","method":"State the linear scale factor, state the volume scale factor, then calculate the volume and state its units","moves":["Write the linear scale factor as the height of the solid you want over the matching height of the one you are given, so it scales in the right direction","Cube that scale factor, because a volume is three-dimensional and scales by the cube of the linear one, then multiply the volume you are given by it","Work that out, and write the volume units beside your answer"]},
  "pythagoras.converse": {"skill":"Compare the two shorter sides squared with the longest squared, and conclude","method":"Square the two shorter sides and add them, square the longest side, compare the two numbers, then say whether it is right-angled and why","moves":["Square the two shorter sides and add them together","Square the longest side on its own","Compare the two totals, then say whether the triangle is right-angled and give that comparison as your reason"]},
  "volume.cone-minus-hemisphere": {"skill":"Subtract the volume of a hemisphere from the volume of a cone","method":"Cone, hemisphere, know to subtract, calculate, round","moves":["Halve the cone's diameter and put that radius and the height into \\(\\frac{1}{3}\\pi r^{2}h\\) for the whole cone","Do the same for the hemisphere — half of \\(\\frac{4}{3}\\pi r^{3}\\), using half of its own diameter as the radius","The part being asked about is what is left once the hemisphere is taken away, so subtract the hemisphere's volume from the cone's","Carry out that subtraction on the unrounded figures, then round as asked and write the cubic units"]},
  "indices.cancel-coefficients": {"skill":"Divide coefficients and powers by their own separate rules","method":"Simplify the powers in the numerator, cancel the constants, then eliminate the variable from the denominator","moves":["Tidy the numerator first by multiplying its terms together and adding the powers of the letter","Divide the numbers at the front on their own, since they follow ordinary division rather than the index laws","Subtract the power underneath from the power above to clear the letter out of the denominator"]},
  "alg-fractions.subtract": {"skill":"Common denominator, expand the numerator watching the sign, collect like terms","method":"Correct common denominator, then correct numerator, then remove the brackets and collect like terms","moves":["Find the lowest denominator both fractions can sit over — multiply the two denominators, unless one already fits inside the other","Multiply each numerator by whatever its denominator was short of, keeping the minus sign in front of the second bracket","Expand the top, letting that minus sign flip the sign of every term inside the second bracket, then collect like terms"]},
  "bearings.three-sides-angle": {"skill":"Three distances on a map, find the angle at one of them","method":"Substitute into the cosine rule, calculate the cosine, calculate the angle; then the back bearing and the shaded angle","moves":["Every side is known and no angle is, which is the cosine rule rearranged for an angle: square and add the two sides meeting at the corner you want, subtract the square of the side facing it, and divide by twice the product of those two sides","Work that whole fraction out to get the cosine, keep the full decimal on the display, then press inverse cosine to turn it into the angle itself","For the bearing part, add \\(180\\) to the bearing you were given, because you are now measuring from a north line at the other end of that same line","Read the diagram to see whether the angle you found turns clockwise or anticlockwise from that back bearing, apply it, and give the result as a three-figure bearing measured clockwise from north, taking \\(360\\) off if you have gone past it"]},
  "change-subject.fraction-coefficient": {"skill":"Clear the fraction first, then isolate the subject","method":"Clear the constant term, clear the fractional coefficient, then divide by what is left","moves":["Read the right-hand side from the outside in and note what has been done to the subject, because you will undo those operations in the reverse order","Deal with anything added or subtracted outside the fraction first, then multiply both sides by the number sitting under the \\(1\\) so the fraction is gone","Divide both sides by whatever is still multiplying the subject, and take across any term still sitting beside it"]},
  "trig-equations.solve": {"skill":"Isolate the ratio, take the inverse, then find both angles in the range","method":"Rearrange the equation, find one value of x, then find the other","moves":["Strip everything away from the trig ratio until it stands on its own — shift the added or subtracted number across first, then divide by whatever multiplies it","Put that ratio through the inverse on your calculator, dropping any minus sign for the moment, to get the reference angle in the first quadrant","Your calculator only ever hands back one angle, so mark the reference angle on a CAST diagram and find the other quadrant where that ratio carries the sign yours has — measuring back from \\(180\\), back from \\(360\\), or on past \\(180\\) as that quadrant requires — then write down both angles"]},
  "sector.segment-major": {"skill":"The whole circle less the sector-minus-triangle","method":"As for the minor segment, with the final mark covering the extra subtraction from the whole circle","moves":["Write the angle at the centre over 360, the share of the circle the small sector takes","Multiply that share by the whole circle's area, \\(\\pi\\) times the radius squared, to get that sector","Find the triangle at the centre with \\(\\frac{1}{2}ab\\sin C\\), using the two radii and the angle between them","Take the triangle from the sector for the small piece, then take that piece away from the whole circle's area to leave the shaded part"]},
  "fractions.subtract-mixed": {"skill":"Subtract mixed numbers, or a fraction from a mixed number","method":"Put both parts over a common denominator, then subtract and tidy the answer up","moves":["Turn each mixed number into a top-heavy fraction, then rewrite both of them over a bottom line that each denominator divides into","Take the second numerator away from the first over that shared bottom line, then write the answer back as a mixed number in its simplest form"]},
  "inequalities.brackets": {"skill":"Expand, collect, solve — and reverse the sign if dividing by a negative","method":"Expand the bracket, then collect like terms, then solve","moves":["Multiply out the bracket, taking the number outside onto each term inside it","Collect the \\(x\\) terms on one side and the plain numbers on the other, leaving the inequality sign as it stands","Divide both sides by the number in front of \\(x\\), flipping the inequality sign round if that number is negative, and give the answer as a range of values rather than a single one"]},
  "angles.tangent-semicircle": {"skill":"Right angle at a tangent, isosceles radii, and the angle in a semicircle","method":"Angle OBD, then EDF from the semicircle, then BDF as their sum","moves":["Subtract the angle at the point of contact from \\(90^{\\circ}\\), since a radius meets a tangent square on, then carry that size across to the far base of the triangle made by two radii","Mark the \\(90^{\\circ}\\) standing on the diameter, the angle in a semicircle, and use the angles of that triangle adding to 180 to find its remaining angle","Add your two angles, as they sit on opposite sides of the diameter and together make the angle asked for"]},
  "expanding.binomial-trinomial": {"skill":"Expand a binomial times a trinomial, giving a term in x cubed","method":"Start to expand, evidenced by any three correct terms, then complete the expansion, then collect like terms","moves":["Multiply every term of the three-term bracket by the first term of the two-term bracket, and write those three products in a row","Do the same with the second term of the two-term bracket, carrying its sign with it, and write those three products underneath the first row","Add the two rows, gathering terms that share a power of \\(x\\), and check that a cube term survives into your final line"]},
  "data.sd-find-a": {"skill":"Read the variance out of a standard deviation given as a root","method":"Find the mean and the squared differences, substitute into the formula for a, then calculate a","moves":["Add the values and divide by how many there are for the mean \\(\\bar{x}\\), then square each value's difference from it and add those squares","Line the given root up against \\(s = \\sqrt{\\frac{\\sum(x - \\bar{x})^{2}}{n - 1}}\\), so \\(a\\) is everything sitting under the root: the total of the squared differences over one less than the number of values","Work that fraction out for \\(a\\), keeping in mind \\(a\\) is the number under the root rather than the standard deviation itself"]},
  "trig-graphs.amplitude-cycles": {"skill":"Read the amplitude off the axis and count the cycles for b","method":"State a, the amplitude read off the y-axis, then state b, the number of complete waves between 0 and 360","moves":["Look at how far the curve climbs above the \\(x\\)-axis at its highest point, reading that distance off the scale on the \\(y\\)-axis — the wave drops the same amount below, and that distance is \\(a\\)","Count how many complete waves are squeezed in along the \\(x\\)-axis between \\(0^{\\circ}\\) and \\(360^{\\circ}\\), and that count is \\(b\\)"]},
  "quadratics.parabola-with-axis": {"skill":"Read a and b off a turning point, then give the axis of symmetry","method":"State a, state b, then state the equation of the axis of symmetry","moves":["Read the turning point's \\(x\\)-coordinate off the graph — the bracket is zero there, so that coordinate is \\(-a\\), and the sign flips when you write \\(a\\) down","Take \\(b\\) from the turning point's \\(y\\)-coordinate, because the bracket adds nothing where it is zero","Give the axis of symmetry as the vertical line through the turning point"]},
  "straight-line.equation-two-points": {"skill":"Find the equation of the line through two given points","method":"Find the gradient from the two points, substitute it and one point into \\(y - b = m(x - a)\\), then tidy the equation into its simplest form","moves":["Subtract the \\(y\\)-coordinates and divide by the difference of the \\(x\\)-coordinates, taking the points in the same order on the top and the bottom, to get the gradient","Put the gradient and either point into \\(y - b = m(x - a)\\), or into \\(y = mx + c\\) to find \\(c\\)","Multiply out any brackets and gather the numbers so the equation finishes with \\(y\\) on its own"]},
  "trig.order-by-size": {"skill":"Order trigonometric values by sign, and say why","method":"State the correct order, then justify it explicitly by the sign of each value","moves":["Put each angle on a CAST diagram and work out the sign of each value from the quadrant it lands in, watching for any angle sitting exactly on an axis","List them smallest first using those signs, then write out in words what the sign of each one is beside your list — that reason carries a mark of its own, so an unexplained ordering throws it away"]},
  "data.median-iqr-compare": {"skill":"Median and IQR, then one comparison of average and one of spread","method":"Find the median and the two quartiles, subtract them for the interquartile range, then write one sentence comparing the medians and another comparing the spreads","moves":["Write the values out in order and pick the middle one for the median","Take the middle of the lower half and the middle of the upper half for the quartiles, then subtract the lower from the upper, halving it if the question asks for the semi-interquartile range","Write one sentence comparing the two medians and name both data sets inside it, because a sentence that does not say whose values are whose scores nothing","Write a second sentence comparing the two spreads, naming both sets again, since the average and the spread carry separate marks"]},
  "simeq.solve-given": {"skill":"Scale, eliminate, substitute back","method":"Multiply one equation so that a letter matches in both, add or subtract to eliminate that letter and get the first value, then substitute back for the second","moves":["Multiply one equation right through, both sides, so that the \\(x\\) terms or the \\(y\\) terms match in size across the two equations","Add or subtract the two equations so that the matching letter cancels away, leaving one equation in a single letter you can work out","Put that answer back into either of the original equations to get the other letter, then write both letters out together"]},
  "alg-fractions.simplify": {"skill":"Factorise numerator and denominator, then cancel","method":"Factorise the numerator, factorise the denominator, then cancel the brackets correctly","moves":["Factorise the top on its own, checking for a factor common to both terms and for a difference of two squares","Factorise the bottom of the fraction the same way, so the denominator is a product of brackets too","Cancel any bracket that now appears on the top and on the bottom, and leave the rest as a single fraction"]},
  "surds.rationalise-simplify": {"skill":"Rationalise a denominator whose surd is not yet in simplest form","method":"Multiply top and bottom by the root in the denominator, take the largest square factor out of the surd that appears, then tidy the fraction","moves":["Multiply top and bottom by the root underneath, which turns the bottom into the whole number that was sitting under that root","The root now on top still has a square factor hiding inside it, so bring that factor's root outside and multiply it into the number already in front","Divide top and bottom by the largest number that goes into both, leaving the root itself untouched"]},
  "indices.evaluate": {"skill":"Evaluate a numeric fractional index by taking the root then the power","method":"Read the bottom of the index as a root and the top as a power, then take the root first and raise the result","moves":["Rewrite the number as a root raised to a power, the bottom of the index telling you which root and the top telling you the power, as in \\(a^{\\frac{m}{n}} = \\left(\\sqrt[n]{a}\\right)^{m}\\)","Take the root first, which keeps the numbers small, then raise that result to the power"]},
  "functions.find-unknown": {"skill":"Given f(a) = b, solve for a","method":"Set the function equal to the value you are given, then solve that equation for the unknown","moves":["Write the formula out again with the unknown letter in place of \\(x\\), and put the whole thing equal to the number the question says \\(f\\) comes out as","Take the number that is added on across to the other side, then divide both sides by the number in front of the letter"]},
  "trig-diagram.cosine-side": {"skill":"Two sides and the angle between them, find the third side","method":"Substitute the two sides and the angle between them into the cosine rule, work out the square of the missing side, then take its square root","moves":["Check that the given angle sits between the two known sides, which is what lets the cosine rule work here, and write \\(a^{2} = b^{2} + c^{2} - 2bc\\cos A\\) with the missing length as \\(a\\)","Put the two lengths and the angle in and work the whole right hand side out in one pass on your calculator — what you get is the square of the missing side, not the side itself","Square root that number to get the length, then round it to the accuracy the question names and add the units"]},
  "vectors.magnitude": {"skill":"Square the components, add, and take an exact square root","method":"Square each component and add them up, then take the square root and leave it exact","moves":["Square each component and add the results together","Take the square root of that total, leaving it exact if it is not a whole number"]},
  "vectors.add-from-grid": {"skill":"Count two vectors off a square grid and add their components","method":"Components of either vector counted off the squares, then the components of the sum","moves":["Count the squares each arrow travels, going across first and then up, with left and down counted as negative","Add the across components together and the up components together, and write the result as one column vector"]},
  "volume.sphere-scientific": {"skill":"Give a sphere's volume in scientific notation, then divide two such volumes","method":"Substitute into the volume of a sphere and evaluate, write that in scientific notation, then set up the division and evaluate it","moves":["Substitute the radius into \\(V = \\frac{4}{3}\\pi r^{3}\\) and work the volume out as an ordinary long number first","Rewrite that number in scientific notation, rounding the front part to the accuracy the question asks for","Read \"how many times greater\" as a division, and write the larger volume over the smaller one","Divide the front numbers and subtract the powers of \\(10\\) to finish"]},
  "alg-fractions.divide": {"skill":"Multiply by the reciprocal, factorise, cancel","method":"Multiply by the reciprocal of the second fraction, factorise the top and the bottom, then cancel what they share","moves":["Flip the second fraction upside down, then multiply by it instead of dividing","Look at the top and the bottom for anything that breaks into factors, such as a difference of two squares","Cancel every factor that appears above and below the line, then multiply what is left across the top and across the bottom"]},
  "percentages.reverse": {"skill":"Divide by the multiplier to recover the original quantity","method":"The amount you are given is more, or less, than 100% of the original, so write down that multiplier, divide by it, and carry the division through","moves":["Decide what percentage of the original the amount you are given is — over 100% after an increase, under it after a decrease","Divide that amount by the matching multiplier to get back to 100%","Carry the division through"]},
  "similarity.triangle-area": {"skill":"The square of the linear scale factor, then a subtraction","method":"Linear scale factor, square it to reach the whole area, then subtract the small triangle","moves":["Write the linear scale factor as the height of the large triangle over the height of the small one","Square that scale factor, because areas scale by the square of the linear one, and multiply the area you are given by it","Work that out, which gives you the area of the whole large triangle","Subtract the small triangle's area from it, since the section you have been asked for is what is left around the outside"]},
  "sector.radius-arc": {"skill":"Angle and arc back to the radius","method":"The correct fraction of the circle, construct the equation, know how to solve it, then solve it and state the radius","moves":["Write the angle over 360 — that is the share of the circle the arc covers","Set that share of the circumference, \\(2\\pi r\\), equal to the arc length you are given","Divide the arc by that fraction to undo it, which leaves the whole circumference","Divide the circumference by \\(2\\pi\\) to get the radius, rounding as asked"]},
  "composite.hexagon-area": {"skill":"Diagonals cut a regular hexagon into six triangles of half ab sin C","method":"Divide 360 by six for the angle at the centre, substitute into the area of a triangle formula, multiply by six for the whole hexagon, then give the area with its units","moves":["Divide 360 by six to get the angle at the centre, then find the length from the centre out to a corner, halving a diagonal if that is what you are given","Put two of those lengths and that centre angle into \\(\\frac{1}{2}ab\\sin C\\) for the area of one triangle","Multiply that area by six, since the six triangles are identical and together they fill the hexagon","Give the total area with square units, rounded the way the question asks"]},
  "bearings.two-bearings": {"skill":"Two places on a cardinal line, a bearing from each, find a distance","method":"Turn the two bearings into the angles inside the triangle, substitute into the sine rule, rearrange it, then work out the distance","moves":["Draw a north line at each point you were given a bearing from and subtract to turn those bearings into angles inside the triangle, then take the two you have off \\(180\\) to get the third","Pair each side with the angle facing it, and write the sine rule with the length you are after over the sine of its own angle on one side, the known pair on the other","Multiply both sides by the sine sitting underneath the missing length, so that length stands alone","Work the fraction out in one pass on your calculator, round to the accuracy the question names, and write the units in"]},
  "form-equation.border": {"skill":"Turn a border of width x into a quadratic, then solve it","method":"Write the expression for the border, form the area equation and rearrange it, then substitute into the quadratic formula, evaluate the discriminant, solve, and select and round the root that is a length","moves":["Follow the length of the tile out to the edge of the board: the border sits at both ends, so the length gains \\(x\\) twice, and the width gains \\(x\\) twice for the same reason — write an expression for each","Multiply those two expressions together and expand them for the area of the whole board, then set that equal to the area you are given and take every term to one side so the quadratic is equal to 0","Read \\(a\\), \\(b\\) and \\(c\\) straight off that quadratic, put them into the quadratic formula, and work out \\(b^{2} - 4ac\\) underneath the square root sign","Take the square root and work the fraction out twice, once with the plus and once with the minus, then throw away the negative value because a border cannot be a negative width, and round what is left to the accuracy the question asks for"]},
  "fractions.brackets": {"skill":"Evaluate the bracket first, then multiply - two operations","method":"Work out the bracket first by putting both fractions over a common denominator, then multiply and tidy the answer up","moves":["Rewrite the two fractions inside the bracket over a bottom line they both divide into, and combine the numerators so the bracket becomes one single fraction","Multiply that single fraction by the one sitting outside the bracket, tops together and bottoms together, then cancel the result down to its simplest form"]},
  "sector.area-angle-pi314": {"skill":"The same with pi taken as 3.14, which is a different sum","method":"Write the angle as a fraction of 360, substitute it into the sector area formula with pi taken as 3.14, then work the area out","moves":["Write the angle over 360 to get the sector's share of the whole circle","Multiply that share by \\(\\pi\\) times the radius squared, putting \\(3.14\\) in place of \\(\\pi\\)","Work the area out with \\(3.14\\), not the calculator's own \\(\\pi\\) button"]},
  "quadratics.discriminant": {"skill":"Calculate \\(b^2-4ac\\) and state the nature of the roots","method":"Calculate the discriminant, then state the nature of the roots","moves":["Pick out \\(a\\), \\(b\\) and \\(c\\) from the equation, keeping any minus signs with them, then put them into \\(b^{2} - 4ac\\)","Look at whether that number comes out positive, zero or negative, and say what that tells you about the roots"]},
  "pythagoras.coordinates-pyramid": {"skill":"The apex of a pyramid sits above the centre of its base","method":"State the coordinates of B, then know how to find AM squared, know how to find AV, and find the length of AV","moves":["Write the missing base corner down by stepping from the given corner through the point directly below the apex, and the same distance on again","Take the difference between that given corner and the apex in each of the three directions","Square those three differences and add them together","Take the square root to get the length from the base corner up to the apex"]},
  "linear-equations.clear-denominators": {"skill":"Multiply every term by the lowest common multiple, then solve","method":"Eliminate the denominators, rearrange into ax = b, solve","moves":["Work out the smallest number both bottom lines divide into, then multiply each term on both sides by it so the fractions clear away","Gather the \\(x\\) terms on one side and the plain numbers on the other, tidying it down to the shape \\(ax = b\\)","Divide both sides by the number in front of \\(x\\), and leave the answer as a fraction in its simplest form rather than a rounded decimal"]},
  "surds.in-function": {"skill":"Substitute into a function, then rationalise the denominator","method":"Substitute the value into the function, then multiply top and bottom by the root to clear the denominator","moves":["Replace every \\(x\\) in the function rule with the number written in the brackets, so you can see the fraction you are actually working with","Multiply that fraction, top and bottom, by the root underneath, so the bottom becomes a whole number"]},
  "quadratics.sketch-completed-square": {"skill":"Read the turning point off completed square form and sketch the curve","method":"Read the turning point off the completed square, sketch a parabola with its minimum there, then mark where it crosses the \\(y\\)-axis","moves":["Find the \\(x\\) that makes the squared bracket zero — a square is never negative, so the curve is at its lowest there, and that fixes both coordinates of the turning point","Draw a parabola opening upwards from that minimum, and annotate the turning point on the sketch","Put \\(x = 0\\) into the equation for the \\(y\\)-intercept, and mark that on the sketch too"]},
  "trig-identities.simplify": {"skill":"Replace \\(\\tan x\\) with \\(\\dfrac{\\sin x}{\\cos x}\\), or take out a common factor, then use \\(\\sin^2 x + \\cos^2 x = 1\\)","method":"Swap \\(\\tan x\\) for \\(\\dfrac{\\sin x}{\\cos x}\\), or take out a common factor, then use \\(\\sin^2 x + \\cos^2 x = 1\\) to simplify what is left","moves":["Scan the terms for a factor they all share and pull it out in front of a bracket — where a \\(\\tan x^{\\circ}\\) blocks that, write it as \\(\\frac{\\sin x^{\\circ}}{\\cos x^{\\circ}}\\) so every term is built from the same two functions","Read what is left inside the bracket against \\(\\sin^{2} x^{\\circ} + \\cos^{2} x^{\\circ} = 1\\): swapping that pair for \\(1\\) lets the rest cancel down"]},
  "form-equation.rectangle-triangle": {"skill":"Derive a quadratic from two equal areas, then solve it for the sides","method":"An expression for the rectangle, then the two areas expanded separately and equated into the printed quadratic, then factorise, solve and reject","moves":["Multiply the length of the rectangle by its breadth, then expand the brackets so its area is a tidy expression in \\(x\\)","Read the base and the height off the triangle — watch for a base written as a multiple of a bracket — put them into half the base times the height, and expand that as well","Set the two expanded areas equal, since the question says they match, and take every term to one side so the quadratic is equal to 0","Factorise that quadratic into two brackets, set each bracket to 0 for the two values of \\(x\\), reject the negative one because a length cannot be negative, and put the survivor back into the rectangle's expressions to get its measurements"]},
  "sci-notation.calculate": {"skill":"Multiply, divide or take a percentage, then express in scientific notation","method":"Correct method, then evaluate and write in scientific notation","moves":["Decide from the wording whether the two quantities are multiplied, or one divided by the other, or a percentage taken of one — a percentage becomes a decimal you multiply by — and write that calculation out with the powers of ten left in","Work it out in one pass on your calculator using the \\(\\times 10^{n}\\) button, then rewrite the display in scientific notation, checking the front number sits between \\(1\\) and \\(10\\) before you commit to it"]},
  "vectors.pathway-parallelogram": {"skill":"Express a diagonal of a parallelogram in terms of two sides","method":"One step: the route round two sides of the parallelogram","moves":["Pick a route between the two corners that uses only sides of the parallelogram, since no side joins them directly","Swap each leg of that route for the lettered vector it copies, remembering opposite sides of a parallelogram are equal, and put a minus in front of any leg travelled against its arrow"]},
  "factorising.fully": {"skill":"Common factor first, then the difference of two squares","method":"Begin to factorise by taking out the common factor, then factorise fully via the difference of two squares","moves":["Look at both terms and find the largest number that divides into each, then write it outside a bracket with whatever is left inside","Now read the bracket: two squared quantities with a minus between them split into two brackets, the same two quantities with a plus in one and a minus in the other. Keep the factor you took out sitting at the front"]},
  "angles.two-tangents-chord": {"skill":"Allied angles across parallel lines, isosceles radii, then a quadrilateral with two right angles","method":"Angle CAO across the parallels, then CAB, then ABC","moves":["Subtract the angle given at the centre from 180 to reach the angle where that radius meets the chord, because the chord and the line it is parallel to trap a pair of angles on the same side that add to 180","Copy that angle to the chord's other end, since the two radii make an isosceles triangle, then take both off 180 for the angle at the centre","Work round the quadrilateral made by the two tangents and the two radii: its angles add to 360 and each tangent meets its radius at \\(90^{\\circ}\\)"]},
  "data.mean-sd-compare": {"skill":"Mean and standard deviation, then compare both with a second sample","method":"Find the mean, square each difference from it, substitute into the standard deviation formula and work it out, then write one sentence comparing the means and another comparing the spreads","moves":["Add the values and divide by how many there are for the mean \\(\\bar{x}\\), then subtract the mean from each value, square each difference and add those squares up","Put that total into \\(s = \\sqrt{\\frac{\\sum(x - \\bar{x})^{2}}{n - 1}}\\), where the top collects the squared differences and the bottom is one less than the number of values, then take the root","Write one sentence comparing the two means and name both groups inside it, because a sentence that leaves out whose values are whose scores nothing","Write a second sentence comparing the two standard deviations, naming both groups again, since the average and the spread carry separate marks"]},
  "volume.cone-minus-cone": {"skill":"Subtract a similar cone from a cone to find the volume of a frustum","method":"Know it is a difference, large cone, small cone, calculate, round","moves":["Read the shape as a cone with its tip cut off, so what is left is one volume take away the other — you need both","Halve the large cone's diameter and put that radius and its height into \\(\\frac{1}{3}\\pi r^{2}h\\)","Do the same for the small cone, using its own radius and its own height","Subtract the small volume from the large one, keeping the unrounded figures until the end, then round and state the cubic units"]},
  "trig-diagram.sine-angle": {"skill":"Pair each side with its opposite angle, then find the acute angle","method":"Pair each side with the angle opposite it and substitute into the sine rule, rearrange to make the sine the subject, then take the inverse to get the angle","moves":["Match each length in the diagram with the angle facing it across the triangle, then feed the two complete pairs into \\(\\frac{\\sin A}{a} = \\frac{\\sin B}{b}\\), putting the sine of the angle you want on top","Multiply both sides by the length underneath that unknown sine so the sine is by itself, then work the right hand side out as a decimal","Take the inverse sine of that decimal to get the acute angle, and round it the way the question asks"]},
  "indices.negative-power": {"skill":"Combine powers to a negative index, then write it with a positive power","method":"Apply the power of a power, then add the powers, then express the result with a positive power","moves":["Deal with the bracket first, multiplying the powers together and keeping the minus sign attached to the power it belongs to","Combine what is left by adding the powers where terms multiply and subtracting them where terms divide","Rewrite the result so the power is positive, using \\(a^{-n} = \\frac{1}{a^{n}}\\)"]},
  "similarity.area-from-cost": {"skill":"Scale a quantity proportional to area by the square of the scale factor","method":"The linear scale factor, know to multiply or divide the cost by its square, then find the cost","moves":["Write the linear scale factor as the length on the shape whose cost you want over the matching length on the other shape","The cost follows the area, so square that scale factor, since areas scale by the square of the linear one, and multiply the cost you are given by it","Work that out, and give the answer as an amount in pounds and pence"]},
  "change-subject.root": {"skill":"Square or take a root to undo the power, then rearrange","method":"Undo the operations in turn, with the square or the square root taken at the point it applies","moves":["Start at the subject and read outwards, noting each thing that has been done to it, because you undo those things in the reverse order","Clear whatever sits outside the square root first, taking a loose term across and dividing by anything multiplying the root, until the root stands alone on its side","Square both sides to remove the root, then undo anything still attached to the subject so that it stands by itself"]},
  "alg-fractions.add": {"skill":"Common denominator, expand the numerator, collect like terms","method":"Correct common denominator, then correct numerator, then remove the brackets and collect like terms","moves":["Multiply the two denominators together to make the denominator both fractions can sit over, and leave it in brackets","Multiply each numerator by the denominator it is missing, so both sit over that single bottom line","Expand the brackets on the top and collect like terms, leaving the bottom in its factorised form"]},
  "composite.split-side-cosine": {"skill":"Cosine from the small triangle, then the cosine rule in the large one","method":"Identify the cosine of the shared angle, substitute into the cosine rule, calculate the square of the side, then calculate the side","moves":["Take the side beside the shared angle over the hypotenuse of the small right-angled triangle to get \\(\\cos\\) of that angle, and keep it as a fraction rather than rounding it","Add the pieces along each arm to get the two full sides of the large triangle that meet at that same angle","Put those two sides and your fraction into the cosine rule to get the square of the side you are after","Square root that total, and round it the way the question asks"]},
  "functions.evaluate": {"skill":"Substitute a value, usually negative, into f(x)","method":"Substitute the value into f(x), then evaluate","moves":["Replace every \\(x\\) in the formula with the number written in the brackets after \\(f\\), wrapping it in brackets of its own so a minus sign is carried into the power","Work out the power first, then the adding and subtracting, until you are left with one number"]},
  "data.quartiles": {"skill":"Order the data, find the quartiles, then the (semi-)interquartile range","method":"Find the quartiles, then calculate the range","moves":["Write the values out smallest to largest, since nothing below works on an unordered list","Mark the median to split the list into a lower and an upper half, then take the middle value of each half for the lower and upper quartiles","Subtract the lower quartile from the upper one for the interquartile range, then halve that if the question asks for the semi-interquartile range"]},
  "fractions.divide-mixed": {"skill":"Divide a mixed number by a fraction or a whole number","method":"Turn the mixed number into an improper fraction and multiply by the reciprocal, then tidy the answer up","moves":["Turn each mixed number into a top-heavy fraction, and write any whole number over 1 so it has a bottom line to work with","Flip the second fraction upside down and multiply by it instead of dividing, then cancel the result down and tidy it into a mixed number"]},
  "coords.pyramid-on-cube": {"skill":"Find the apex of a pyramid over the centre of the solid beneath it","method":"State one coordinate, state the other","moves":["Get the cube's side length from the labelled point, as that one measurement fixes every edge of it","Read the far top corner of the cube off the diagram, putting the side length into each coordinate that has moved away from the origin and 0 into any that has not","For the apex, halve the side length for both horizontal coordinates because it sits over the centre, then stack the pyramid's own height on top of the cube's"]},
  "trig-diagram.area-exact": {"skill":"Half ab sin C with the sine given as a fraction, no calculator","method":"Substitute the two sides and the sine you are given into \\(\\frac{1}{2}ab\\sin C\\), then work the area out exactly","moves":["Check that the angle whose sine you have been handed is the one between the two given lengths, then set up \\(\\text{Area} = \\frac{1}{2}ab\\sin C\\) with those lengths in place","Slot the fraction you were given straight in where \\(\\sin C\\) goes rather than reaching for a calculator, then cancel the numbers down to a single exact value and add the square units"]},
  "angles.tangent-meets-diameter": {"skill":"Isosceles radii, a straight line at the centre, then the triangle outside the circle","method":"Angle OBD, then ODB from the isosceles radii, then CAB","moves":["Take the angle given at the point of contact away from \\(90^{\\circ}\\), because a radius meets a tangent at right angles","That radius and the one to the chord's other end make an isosceles triangle, so double your angle and subtract from 180 for the angle at the centre, then take that off 180 again as the diameter carries on as a straight line","Finish in the triangle sitting outside the circle, where the angles add to 180 and the corner at the point of contact is the right angle with the tangent"]},
  "change-subject.fraction": {"skill":"Multiply up, subtract, divide — the subject sits in a numerator","method":"Multiply by the denominator, subtract the constant term, divide by the coefficient","moves":["Get rid of the fraction first by multiplying both sides by the denominator, which undoes the dividing","Take the term that is added on beside the subject across to the other side, leaving only the subject and the number in front of it","Divide both sides by that number in front of the subject, then write the subject on its own on the left"]},
  "data.sd-surd": {"skill":"Express the standard deviation of five values in the form \\(\\dfrac{a\\sqrt{b}}{2}\\)","method":"Find the mean, find the squared differences, substitute into the formula and start to evaluate, then state a and b","moves":["Add the values and divide by how many there are to get the mean \\(\\bar{x}\\)","Subtract the mean from each value, square every difference, and add them for \\(\\sum(x - \\bar{x})^{2}\\)","Put that total into \\(s = \\sqrt{\\frac{\\sum(x - \\bar{x})^{2}}{n - 1}}\\), then split the root top and bottom, as the root of the bottom comes out whole and becomes the denominator you have been given","Simplify the root on top by pulling out its largest square factor, then read off \\(a\\) and \\(b\\) by matching what you have against \\(\\frac{a\\sqrt{b}}{2}\\)"]},
  "simeq.intersection": {"skill":"Solve the pair to find where two lines cross, answer as coordinates","method":"Scale one equation so the \\(x\\) or the \\(y\\) terms match, eliminate that letter and solve for both values, then write them as coordinates","moves":["Multiply one of the two equations right through so the \\(x\\) terms or the \\(y\\) terms match in size across both","Add or subtract the equations to cancel that matching letter, work out the letter left behind, then put it back into either equation for the other one","Write the pair as coordinates in brackets with the \\(x\\) one first, because the question asks for the point where the lines meet"]},
  "quadratics.parabola-from-axis": {"skill":"Take a from the axis of symmetry, then substitute a point for b","method":"State a from the axis of symmetry, then substitute the marked point and state b","moves":["Match the axis of symmetry to the turning point, where the bracket is zero, so its \\(x\\) value is \\(-a\\) — and mind the sign as you write \\(a\\) down","Substitute the marked point's coordinates into \\(y = (x + a)^{2} + b\\) now that you have \\(a\\)","Work out the bracket, then rearrange to leave \\(b\\) on its own"]},
  "similarity.triangle-part": {"skill":"Equal ratios across a parallel cut, then an equation in x","method":"Scale factor, form the equation, solve for x","moves":["The parallel line makes the small triangle and the whole triangle similar, so write the two parallel sides as a fraction, small over large","Set the side down the sloping edge of the small triangle over the whole of that edge equal to that fraction, remembering the whole edge is \\(x\\) plus the piece added on below it","Cross-multiply, gather the \\(x\\) terms on one side and the number on the other, then work \\(x\\) out"]},
  "quadratics.formula": {"skill":"Substitute into the formula and round as the question asks","method":"Substitute \\(a\\), \\(b\\) and \\(c\\) into the quadratic formula, work out the discriminant under the root, then give both roots rounded as the question asks","moves":["Pick out \\(a\\), \\(b\\) and \\(c\\) from the equation, keeping any minus signs with them, then write \\(x = \\frac{-b \\pm \\sqrt{b^{2}-4ac}}{2a}\\) out with those numbers in place","Work out the discriminant under the root on its own first, so the rest of the arithmetic stays manageable","Work out both roots, taking the plus and then the minus, and round each to the accuracy the question asks for"]},
  "volume.sphere-shell": {"skill":"Find the volume of a coating from the outer diameter and its thickness","method":"Know it is a difference, outer sphere, inner sphere, calculate, round","moves":["Halve the width across the outside to get the outer radius, then subtract the thickness of the coating from it to reach the radius underneath","Put the outer radius into \\(\\frac{4}{3}\\pi r^{3}\\) for the volume of the whole thing","Put the inner radius into that same formula for the volume of the sphere sitting inside","Subtract the inner volume from the outer one to leave only the coating, then round as asked and write the cubic units"]},
  "pythagoras.converse-joined": {"skill":"Two triangles joined along a shared edge: build the base, then test the composite","method":"Add the two parts together to get the shared base, then square and add the two shorter sides and compare with the longest squared, giving your conclusion and its reason together","moves":["Add the two part-lengths along the base together to get the whole base, which is the longest side of the triangle","Square the two shorter sides and add them together, then square that longest side on its own","Compare the two totals, then say whether the triangle is right-angled and give that comparison as your reason"]},
  "vectors.pathway-extended": {"skill":"Use an extended side and a midpoint to reach a fourth point","method":"State the direct route, then take the pathway through the extension and the midpoint, and collect it","moves":["Travel along the vector you are given from one corner, then back against the other one, to write the third side in terms of both letters","Set off along the extended piece, which repeats the side it continues, then add half of that third side to land on its midpoint","Multiply the half through the bracket and collect the terms in each letter"]},
  "alg-fractions.factorise-simplify": {"skill":"Factorise, then hence simplify — the scaffolded two-part form","method":"Factorise for part (a), then factorise the denominator and simplify for part (b)","moves":["Factorise the expression in part (a) fully — check for a factor common to both terms, and for a difference of two squares","Carry that factorised form into part (b) as the top, then factorise the denominator into brackets","Cancel the bracket the top and the bottom share, and leave the rest as one fraction in its simplest form"]},
  "straight-line.gradient-from-equation": {"skill":"Rearrange into y = mx + c and read off the gradient","method":"Isolate the term in y, or divide throughout, then state the gradient explicitly","moves":["Shift everything except the term in \\(y\\) over to the other side of the equals sign, changing signs as you go","Divide every term by the number in front of \\(y\\), and whatever is then multiplying \\(x\\) is the gradient — sign included"]},
  "indices.root-as-power": {"skill":"Write a reciprocal root as a single negative fractional power","method":"Apply \\(\\sqrt[n]{x^m} = x^{m/n}\\), then apply \\(\\dfrac{1}{x^n} = x^{-n}\\)","moves":["Rewrite the root as an index, with the power from inside going on top and the root number underneath, as in \\(\\sqrt[n]{a^{m}} = a^{\\frac{m}{n}}\\)","That power now sits under \\(1\\), so flip it up by making the index negative, \\(\\frac{1}{a^{n}} = a^{-n}\\)"]},
  "sector.angle-arc": {"skill":"The arc as a fraction of the circumference gives the angle","method":"An expression for the arc length, or the arc-to-circumference ratio, then know how to find the angle from it, then calculate the angle","moves":["Work out the whole circumference, \\(\\pi\\) times the diameter, so you have something to measure the arc against","Divide the arc by that circumference, then multiply by 360, since a full turn is 360 degrees","Work that out and give the angle at the centre in degrees"]},
  "trig-equations.in-formula": {"skill":"Solve a given height formula for the angle, in a range","method":"Substitute the given height into the formula, rearrange it, calculate one value of x, then the second","moves":["Put the height the question hands you in place of \\(h\\) in the formula, so the angle is the only thing left unknown","Rearrange until the \\(\\cos\\) term stands alone — take the constant across, then divide by the number in front, keeping any minus sign attached to the ratio","Run that ratio through the inverse on your calculator, ignoring its minus sign if it has one, to get the reference angle","The calculator gives only one angle, so put the reference angle on a CAST diagram and take both places where the cosine carries the sign yours does — measured back from \\(180\\) or back from \\(360\\) — then give both angles in the range asked for"]},
  "fractions.add-mixed": {"skill":"Add mixed numbers, or a mixed number and a fraction","method":"Put both parts over a common denominator, then add them and tidy the answer up","moves":["Turn each mixed number into a top-heavy fraction, then rewrite both of them over a bottom line that each denominator divides into","Add the two numerators over that shared bottom line, then turn the top-heavy total back into a mixed number and cancel it down"]},
  "expanding.product-plus": {"skill":"Expand a product and a single bracket, then collect like terms","method":"Expand the product two terms at a time, expand the single bracket, then collect the like terms","moves":["Deal with the pair of brackets on its own first: take each term of one across both terms of the other and tidy that part up before you look at anything else","Multiply out the remaining bracket by whatever sits in front of it, watching for a minus there, because it flips both signs inside","Write the two expansions side by side, then gather the squared terms, the \\(x\\) terms and the plain numbers into one term each"]},
  "factorising.solve": {"skill":"Factorise, then set each bracket to zero","method":"Correct factorisation, then solve for x","moves":["Hunt for the pair of numbers that multiply to give the constant and add to give the coefficient of \\(x\\), then write the left hand side as two brackets","Two things multiplying together can only give 0 if one of them is 0, so set each bracket to 0 in turn and solve the two small equations that gives you"]},
  "angles.polygon-produced": {"skill":"Interior angle of a regular polygon, then the angles of a triangle","method":"Interior angle of the polygon (or the angle at the outside point), then the angle asked for","moves":["Count the sides of the polygon, then find the angle at one of its corners: subtract 2 from that count, multiply by 180 and divide by the number of sides","Take that corner angle off 180 where the side is produced into a straight line, then subtract both known angles from 180 in the triangle, because the angles of a triangle add to 180"]},
  "cosine-rule.side-exact": {"skill":"Substitute a given cosine into the cosine rule for an exact side","method":"Substitute the two sides and the cosine you are given into the cosine rule, work out the square of the missing side, then take its square root","moves":["Name the missing side as the one facing the angle whose cosine you were handed, and write \\(a^{2} = b^{2} + c^{2} - 2bc\\cos A\\) with the letters from your own triangle in it","Put the two known lengths and the fraction straight in, then work the right hand side through — the bottom of the fraction cancels against the \\(2bc\\), which is what keeps the arithmetic whole","What you are left with is the square of the side, so take its square root and write the length down with its units"]},
  "surds.rationalise": {"skill":"Multiply top and bottom by the root, then simplify","method":"Multiply top and bottom by the root in the denominator, then tidy what is left","moves":["Write the root that sits underneath over itself as a second fraction and multiply, which turns the bottom into the whole number that was under the root","Look for a number that divides both the top number and the bottom number, and cancel the fraction down by it, leaving the root alone"]},
  "trig.related-angle": {"skill":"Use the quadrant to put the right sign on a known trigonometric value","method":"Find the related acute angle, recall its exact value, then give it the sign that quadrant requires","moves":["Write your angle as a distance from \\(180\\) or from \\(360\\) — that tells you the related acute angle and which quadrant you have landed in","The size of the value is unchanged from the one you were given, so keep that number and attach the sign that function carries in that quadrant, which a CAST diagram settles for you"]},
  "coords.prism": {"skill":"Use an isosceles cross-section to place the far corner of a prism","method":"State one coordinate, state the other","moves":["Pick out which axis the prism's length runs along, and which pair of points each given edge length joins","For the corner directly behind a labelled point, keep its other two coordinates and change only the one running along the prism's length","Use the two equal sloping edges to place the last corner: it sits as far past the peak of the triangle as the given base point sits before it, and it rests on the ground so its height is 0"]},
  "indices.coefficient": {"skill":"Apply the power to the coefficient as well as the variable","method":"Take the power to the number at the front as well as to the letter, then multiply the two results together","moves":["Split the bracket into its number part and its letter part, because the outside power lands on both, \\((ab)^{m} = a^{m}b^{m}\\)","Work out the number raised to that power, multiply the powers of the letter together, then write the two results side by side"]},
  "quadratics.sketch-factorised": {"skill":"Take the roots from the brackets, halve between them, and sketch","method":"Identify the roots, then the turning point or the y-intercept, then both of them on a consistently annotated sketch","moves":["Set each bracket equal to zero in turn and solve — those two \\(x\\) values are where the curve crosses the \\(x\\)-axis","Take the value halfway between them for the turning point's \\(x\\), since a parabola is symmetrical, then substitute it back for the \\(y\\)","Put \\(x = 0\\) for the \\(y\\)-intercept, then draw the parabola with the roots, the turning point and that intercept all annotated"]},
  "volume.pyramid-height": {"skill":"Find the height of a square-based pyramid from its volume","method":"Substitute into \\(V = \\dfrac{Ah}{3}\\) and solve","moves":["Put the base and an unknown height into \\(V = \\frac{1}{3}Ah\\), setting it equal to the volume you were given","Square the base length to get the area \\(A\\), and tidy the left-hand side into a single multiple of \\(h\\)","Divide the volume by that multiple to leave \\(h\\) on its own, and write the height with its units"]},
  "quadratics.complete-square-surd-roots": {"skill":"Complete the square, read off the axis, then solve for surd roots","method":"Complete the square and read the axis of symmetry straight off it; then set the completed square to zero, take the square root of both sides keeping both signs, and simplify the surd","moves":["Halve the coefficient of \\(x\\) for the bracket, then take off what squaring it carries in and bring the constant down beside it","Give the axis of symmetry as the vertical line through the turning point, where the bracket is zero","Set that completed square equal to zero, then take the square root of both sides, keeping both the plus and the minus","Simplify the surd by pulling out the largest square factor, then match what you are left with to the form the question asks for"]},
  "sector.arc-angle": {"skill":"Radius and angle to the arc length, major or minor","method":"Write the angle as a fraction of 360, substitute the radius into the arc length formula, then work the arc out","moves":["Write the angle over 360 — for a major arc that is the angle going the long way round","Multiply that fraction by the whole circumference, \\(\\pi\\) times the diameter, and the diameter is twice the radius","Work the arc length out and round it as the question asks"]},
  "volume.sphere": {"skill":"Halve the diameter, substitute into the volume of a sphere, and round","method":"Substitute, evaluate, round","moves":["Pick out the radius — it is half the width across the sphere, and the formula is built from \\(r\\), not the diameter","Put that radius into \\(V = \\frac{4}{3}\\pi r^{3}\\), cubing it before multiplying","Work the volume out, then round it to the accuracy the question asks for and write the units in cubic form"]},
  "composite.straight-line-angle": {"skill":"The angle given is on the line, so the triangle takes its supplement","method":"Take the supplement of the angle you are given, because it sits on a straight line, then substitute into the sine rule, rearrange it, and find the length","moves":["Work out the angle inside the triangle at that corner by taking the marked angle from 180 — the two of them together fill the straight line","Pair that angle with the side facing it in the sine rule, alongside the given side and its own opposite angle, then rearrange to make the wanted length the subject","Work that length out and round it the way the question asks"]},
  "vectors.pathway-multiples": {"skill":"Follow a route of four edges, two of them multiples of the given pair","method":"The pathway the long way round, then writing each piece as a multiple and collecting","moves":["Build a pathway from the start point to the end point out of the edges you have been told about, going the long way round since none of them joins the two directly","Replace each edge with the multiple of the lettered vectors it stands for, flipping the sign wherever you travel against an arrow, then collect the like terms"]},
  "bearings.three-sides-bearing": {"skill":"Cosine rule for the angle, then add or subtract from a given bearing","method":"Substitute the three sides into the cosine rule, work out the cosine, take the inverse to get the angle, then measure that angle from north to turn it into a bearing","moves":["All three sides are known and no angle is, so square and add the two sides that meet at the corner you want, subtract the square of the side facing that corner, and divide the lot by twice the product of those two sides","Work the top and the bottom out and divide, which leaves you the cosine of that angle rather than the angle — keep the full decimal on your calculator","Press inverse cosine on that decimal to get the angle at the corner","Read the diagram to see which way that angle turns from the bearing you were given, then write the answer as a three-figure bearing measured clockwise from north, rounded as the question asks"]},
  "straight-line.intercept-from-equation": {"skill":"Set x = 0 to find where the line crosses the y-axis","method":"Substitute x = 0, or isolate the term in y, then state the coordinates","moves":["Replace \\(x\\) with 0, which kills off the \\(x\\) term, and solve what is left for \\(y\\)","Write your answer as a pair of coordinates inside brackets with 0 as the first number, since a lone value is not a point"]},
  "pythagoras.space-diagonal-fits": {"skill":"Space diagonal, then decide whether an object fits inside","method":"Find the face diagonal, then the space diagonal, work its length out, then compare it with the object and say whether it fits","moves":["Square the length and the width of the base and add them to get the diagonal across the base, squared","Add the height squared onto that total, with no need to square-root in between","Take the square root to get the space diagonal, the longest straight line inside the cuboid","Compare that length with the object, then say whether it fits and give the comparison as your reason"]},
  "sector.triangle-minus-sector": {"skill":"Subtract a sector from the triangle that shares its apex and its angle","method":"The triangle by \\(\\tfrac{1}{2}ab\\sin C\\), the fraction of the circle, the sector area, know to subtract, then evaluate with units","moves":["Find the triangle first: it has two sides with the angle between them, so use \\(\\frac{1}{2}ab\\sin C\\)","Write the sector's angle over 360, and it is the same angle that sits at the apex","Multiply that fraction by the whole circle's area, \\(\\pi\\) times the radius squared, to get the sector","Take the sector away from the triangle, work the shaded area out and put the units on it"]},
  "similarity.not-similar": {"skill":"Assume similar, find the contradiction, then scale back with a cube root","method":"Find the linear scale factor and cube it for the volume, compare that with the volume you are given and say why they cannot be similar; then use the real volume scale factor and take its cube root","moves":["For part (a), treat the two solids for the moment as if they were similar, and write the linear scale factor as one length over the matching length on the other","Cube that scale factor, because volumes scale by the cube of the linear one, and multiply the volume you are given by it to see what the other volume would have to be","Compare that with the volume the solid actually holds, and write a sentence saying what the mismatch tells you about the two solids","For part (b) the solids really are similar, so divide the new volume by the original volume to get the volume scale factor, take its cube root to come back down to a length, and multiply the original length by it"]},
  "sector.arc-angle-pi314": {"skill":"The same with pi taken as 3.14, which is a different sum","method":"Write the angle as a fraction of 360, substitute it into the arc length formula with pi taken as 3.14, then work the arc out","moves":["Write the angle over 360 to get the arc's share of the way round the circle","Multiply that share by \\(\\pi\\) times the diameter, doubling the radius for the diameter and taking \\(\\pi\\) as \\(3.14\\)","Work the arc length out with \\(3.14\\) rather than the calculator's own \\(\\pi\\)"]},
  "straight-line.best-fit-grid": {"skill":"Read two points off a ruled scattergraph, find the line, then use it","method":"3 + 1, the same four as straight-line.best-fit - gradient, substitute a point, state the equation in the question letters, then evaluate","moves":["Choose two points where the line of best fit passes exactly through a corner of the grid, so both coordinates can be read off the axes without guessing","Take the change up between those points and divide it by the change across to get the gradient","Feed the gradient and one of the points into \\(y = mx + c\\), find \\(c\\), and write the equation in the letters the question uses rather than \\(x\\) and \\(y\\)","Put the value asked about in the second part into your equation to get the missing measurement"]},
  "quadratics.parabola-maximum": {"skill":"Read a maximum turning point off a graph and match it to \\(y = b - (x - a)^2\\)","method":"The axis of symmetry from the turning point, then a, then b","moves":["Give the axis of symmetry as the vertical line through the maximum turning point, taking its \\(x\\)-coordinate","Set the bracket to zero at that turning point — the square is being subtracted, so \\(y\\) is largest there — and read \\(a\\) off, minding the sign","Take \\(b\\) from the height of the turning point, because the bracket contributes nothing where it is zero"]},
  "vectors.components-midpoint": {"skill":"Follow a pathway through a midpoint, in component form","method":"Write the direct route down first, then go round through the midpoint instead, and collect the components","moves":["Travel from one corner of the triangle to the far one by way of the corner in between, adding the two columns to express that route in component form","Set off from the midpoint instead: take half of the column vector for the side it lies on, then travel the second given vector","Add those columns together and write out the components of that pathway"]},
  "angles.polygon-diameter": {"skill":"Equal angles at the centre of a regular polygon, a straight line, then isosceles radii","method":"Angle AOB from the equal division, then FOB on the straight line, then OFB","moves":["Divide 360 by the number of corners the shape has, because its vertices are spread evenly round the circle and share the turn at the centre equally","Subtract that from 180 for the angle next to it at the centre, since the diameter runs straight across","Finish in the triangle made by two radii: it is isosceles, so take the centre angle off 180 and halve what is left"]},
  "surds.rationalise-quotient": {"skill":"Divide one surd by another and leave a rational denominator","method":"Multiply top and bottom by the root in the denominator, tidy the numerator, then tidy the whole fraction","moves":["Multiply top and bottom by the root underneath, so the two roots on top join into a single root and the bottom becomes a whole number","Take the largest square factor out of the root on top and bring the root of that factor outside, in front of what is left","Cancel the number in front of the root against the number underneath by dividing both by their highest common factor"]},
  "trig-graphs.turning-point": {"skill":"Compute a turning point of a shifted trigonometric graph","method":"Find the x of the turning point by shifting the unshifted one, then state the coordinates","moves":["Ask where the plain wave would turn first — \\(\\cos x^{\\circ}\\) peaks at \\(x = 0\\) — then slide that \\(x\\) along by the amount in the bracket, moving right when the bracket subtracts, to get the \\(x\\)-coordinate","Take the number multiplying the \\(\\cos\\) or \\(\\sin\\): that is how far the curve reaches from the \\(x\\)-axis, so give it the sign matching which side of the axis the marked point is on, and write the two values as a coordinate pair"]},
  "quadratics.lands-below": {"skill":"Solve a quadratic model for the moment it falls below where it started","method":"Evaluate the height at a given time, then set the equation equal to the negative drop, rearrange to zero, factorise and reject the negative root","moves":["Put the time you are given into the height formula and work the arithmetic through","Write the height below the starting point as a negative, and set the formula equal to it","Gather every term on one side so the quadratic equals zero, then factorise it","Set each bracket to zero, then reject the negative time — a time cannot run backwards"]},
  "percentages.compound-between-years": {"skill":"Count the years between two dates, then apply the multiplier that many times","method":"Multiplier, then the number of years worked out from the two dates, then evaluate","moves":["Turn the percentage change into a multiplier","Count the years between the two dates, then raise the multiplier to that power and multiply the starting amount by it","Work the multiplication out"]},
  "trig-diagram.area": {"skill":"Half ab sin C, with the angle between the two given sides","method":"Substitute the two sides and the angle between them into \\(\\frac{1}{2}ab\\sin C\\), then work the area out","moves":["Pick out the angle sitting between the two lengths you have been given, since the area formula only works with that one, and write \\(\\text{Area} = \\frac{1}{2}ab\\sin C\\) with those lengths as \\(a\\) and \\(b\\)","Put the lengths and the angle in, work it through with your calculator in degree mode, then round as the question asks and finish with square units"]},
  "coords.cone": {"skill":"Place a circle from the two axes it touches, then a point above it","method":"State one coordinate, state the other","moves":["Halve the given diameter for the radius, which is how far the centre of the base sits from each axis the circle touches","Write down the point of contact: it takes the radius for the coordinate running along the axis it touches, and 0 for the other two","For the point above the centre, use the radius for both horizontal coordinates and the cone's full height for the third"]},
  "trig-diagram.cosine-angle": {"skill":"Three sides, find an angle — often the smallest","method":"Substitute the three sides into the cosine rule rearranged for \\(\\cos A\\), work out the cosine, then take the inverse to get the angle","moves":["Call the side facing the angle you want \\(a\\), and the two sides meeting at that angle \\(b\\) and \\(c\\), then write the cosine rule in its rearranged shape, \\(\\cos A = \\frac{b^{2} + c^{2} - a^{2}}{2bc}\\)","Put the three lengths in and work the fraction out as a single number, keeping its minus sign if the top comes out below zero","Take the inverse cosine of that number to get the angle, then round it as the question asks"]},
  "volume.cylinder-plus-hemisphere": {"skill":"Add a hemisphere to a cylinder, working the cylinder's height out of the total","method":"Hemisphere, cylinder, know to add, calculate, round","moves":["Halve the diameter to get the radius shared by the dome and the cylinder, then find the dome as half of \\(\\frac{4}{3}\\pi r^{3}\\)","Take the dome's own height, which is that same radius, off the total height — what is left is the cylinder's height","Put the radius and that height into \\(\\pi r^{2}h\\) for the cylinder","Add the two volumes, then round as asked and state the cubic units"]},
  "percentages.surcharge": {"skill":"Find a surcharge from the total that includes it","method":"The total is 100% plus the extra, so divide back to the bill before it, then subtract to leave the surcharge itself","moves":["The total already has the charge in it, so it is 100% plus the rate","Divide by that multiplier to get back to the amount before the charge was added","Subtract that from the total, because the question asks for the extra and not the bill"]},
  "pythagoras.converse-from-total": {"skill":"The same, but one distance has to be found from the total first","method":"Work the missing distance out of the total first, then square and add the two shorter sides, compare that with the longest squared, and give your conclusion with a reason","moves":["Take the two given distances away from the total to find the missing third side","Square the two shorter sides and add them together, then square the longest side on its own","Compare the two totals, checking whether they come out equal","Say whether that angle is a right angle, giving the comparison as your reason"]},
  "sector.similar-sectors": {"skill":"Scale an area between similar sectors, and recover a sector angle from its area","method":"The linear scale factor, squared for areas, evaluated; then the larger sector area as a fraction of its circle, rearranged for the angle, evaluated","moves":["For part (a), write the linear scale factor as one radius over the matching radius of the other sector","Square that scale factor, because areas scale by the square of it, multiply the area you are given by it and work the other area out","For part (b), set the angle over 360 times the whole circle's area equal to the larger sector's area","Rearrange that equation to leave the angle on its own, then work the angle out"]},
  "alg-fractions.gradient-context": {"skill":"Substitute into the gradient formula, then simplify","method":"Substitute the two points into the gradient formula, factorise the numerator as a difference of two squares, then take the common factor out of the bottom and cancel","moves":["Label the two points, then put their coordinates into the gradient formula \\(m = \\frac{y_{2} - y_{1}}{x_{2} - x_{1}}\\)","Factorise the numerator, which is a difference of two squares, into two brackets","Take the common factor out of the denominator, then cancel the bracket it shares with the top"]},
  "indices.root-denominator": {"skill":"Turn a root into a fractional index so the division law applies","method":"Use \\(a^m \\times ka^n = ka^{m+n}\\) on the top, write the square root as a power of a half, then subtract the indices to divide","moves":["Multiply out the numerator first, adding the powers of the letter and leaving the number at the front as it is","Rewrite the square root underneath as \\(a^{\\frac{1}{2}}\\), so top and bottom are both powers of the same letter","Subtract that half from the power on top, and leave the answer carrying its fractional power"]},
  "trig-identities.expand": {"skill":"Expand the square, then collect \\(\\sin^2 x + \\cos^2 x\\) into \\(1\\)","method":"Expand the brackets, then simplify using sin squared plus cos squared equals one","moves":["Multiply the bracket out against itself, term by term as you would with any squared bracket, keeping every product before you tidy anything","Gather the two matching middle terms into one, then replace \\(\\sin^{2} x^{\\circ} + \\cos^{2} x^{\\circ}\\) with \\(1\\), since that pair always adds to \\(1\\)"]},
  "composite.height-from-two-angles": {"skill":"Two elevations from the ends of a base, find the height between them","method":"Substitute into the sine rule and rearrange it to get the slant length, then put that length into the right-angled triangle and use it to find the height","moves":["Fill in the missing angle at the top of the slanted triangle by taking both angles of elevation away from 180","Pair the base length with the angle facing it in the sine rule, and the slant distance up to the object with the angle facing that, then rearrange and work the slant distance out","Use that slant distance as the hypotenuse of the right-angled triangle made by dropping the height to level ground, with the angle of elevation at that end, to reach the height"]},
  "volume.cone-approx-pi": {"skill":"Volume of a cone with pi taken as 3.14, without a calculator","method":"Substitute then calculate, keeping the fraction and 3.14 visible","moves":["Halve the diameter for the radius, then put it and the height into \\(V = \\frac{1}{3}\\pi r^{2}h\\), writing \\(3.14\\) in place of \\(\\pi\\)","Work through it by hand — multiply the radius squared by the height, take a third of that, then multiply by \\(3.14\\)"]},
  "angles.tangent-diameter": {"skill":"Straight line at the centre, isosceles radii, then the right angle at the tangent","method":"Angle COE at the centre, then OCE from the isosceles radii, then ACE","moves":["Subtract the angle you are given from 180, because the diameter runs straight through the middle and the angles sitting along it add to 180","Drop into the triangle made by the two radii: it is isosceles, so take that centre angle off 180 and halve what is left to get each equal base angle","Add the \\(90^{\\circ}\\) between the radius and the tangent onto that base angle, since the tangent touches at the very end of that radius"]},
  "quadratics.turning-point": {"skill":"Complete the square, then read off the turning point","method":"Halve the coefficient of \\(x\\) for the bracket, take off what it adds on, then read the turning point straight off the completed square","moves":["Halve the coefficient of \\(x\\) — that number goes inside the bracket, and the bracket is squared","Take off the extra term that squaring the bracket adds on, and bring the constant down beside it","Read the turning point off the completed square — the bracket is zero at the \\(x\\) that empties it, and the number left outside is the \\(y\\)-coordinate there"]},
  "change-subject.fraction-two-step": {"skill":"Multiply up and subtract — the subject has no coefficient to divide out","method":"Multiply by the denominator, then subtract the constant term","moves":["Clear the fraction by multiplying both sides by the denominator underneath, which undoes the dividing","Take the term sitting beside the subject across to the other side, which undoes the adding and leaves the subject by itself"]},
  "cosine-rule.angle-exact": {"skill":"Rearrange the cosine rule and give the cosine as a fraction","method":"Rearrange the cosine rule to make \\(\\cos A\\) the subject and substitute the three sides, then leave the cosine as a fraction in its simplest form","moves":["Spot which side faces the angle you are asked about, because that is the one subtracted on the top line while the two meeting at the angle are squared and added: \\(\\cos A = \\frac{b^{2} + c^{2} - a^{2}}{2bc}\\)","Put the three lengths in, work the top line and the bottom line out as whole numbers, then cancel the fraction down by whatever divides into both rather than turning it into a decimal"]},
  "alg-fractions.divide-simple": {"skill":"Multiply by the reciprocal, then cancel a repeated factor","method":"Start the division by multiplying by the reciprocal, then simplify","moves":["Flip the second fraction upside down and multiply by that reciprocal instead of dividing","Cancel one copy of the repeated bracket against the matching one underneath, then multiply the rest across"]},
  "surds.expand-bracket": {"skill":"Expand, simplify the resulting surd, then collect like surds","method":"Expand the bracket, take the largest square factor out of the surd that appears, then collect the like surds together","moves":["Multiply the term in front of the bracket by each term inside it, remembering that a root times itself gives the whole number that was underneath","Multiplying two different roots leaves one new root, so split it into its largest square factor times what is left and bring the root of that square factor outside","Gather the terms that share the same root by adding their coefficients, and leave the whole number sitting on its own"]},
  "form-equation.triangle-rectangle": {"skill":"Equate a triangle and a rectangle, clear the fraction, solve","method":"Write the triangle's area, equate it to the rectangle's, start to solve, rearrange, then solve","moves":["Take the base and the height marked on the triangle and put them into half the base times the height, keeping the bracket as it stands rather than expanding it","Write the area of the rectangle as its length times its breadth, then set the two areas equal because the question tells you they match","Multiply both sides by 2 to clear the half, expand the brackets, gather the \\(x\\) terms on one side and the plain numbers on the other, then divide by whatever is left multiplying \\(x\\)"]},
  "volume.box-plus-sphere": {"skill":"Add a sphere to a cuboid, working the cuboid's height out of the total","method":"Sphere, cuboid and add, calculate with units","moves":["Halve the sphere's diameter and put that radius into \\(\\frac{4}{3}\\pi r^{3}\\)","Take the sphere's full width off the total height to get the cuboid's height, then multiply it by the two base lengths","Add the two volumes together and write the answer with its cubic units"]},
  "pythagoras.space-diagonal": {"skill":"Face diagonal first, then the space diagonal","method":"Use Pythagoras across the base to get the face diagonal, then use it again with the height, and work the length out","moves":["Square the length and the width of the base and add them, which gives the diagonal across the base, squared","Add the height squared onto that total, with no need to square-root in between","Take the square root to get the space diagonal, the longest straight line that fits inside the cuboid"]},
  "trig-identities.fractions": {"skill":"Split into separate fractions, then simplify each","method":"Express as separate fractions, then simplify","moves":["Break the top up so that each term on the numerator sits over the denominator as a fraction of its own, joined by the sign that was between them","Tidy each piece separately — one cancels down to the plain number in front of it, and a \\(\\frac{\\sin x^{\\circ}}{\\cos x^{\\circ}}\\) left over is simply \\(\\tan x^{\\circ}\\)"]},
  "composite.two-elevations": {"skill":"Two elevations from one side, using the angle on a straight line","method":"Use the angle on the straight line to fill in the triangle, substitute into the sine rule and rearrange it for the slant length, then use that length to reach the distance along the ground","moves":["Subtract the nearer angle of elevation from 180 to get the angle inside the triangle there, because that angle and the elevation sit together on the level ground, then take that and the far elevation from 180 for the angle at the top","Pair the distance between the two viewing points with the angle facing it in the sine rule, against the slant length up to the top and its own opposite angle, and rearrange to make the slant length the subject","Work that slant length out — it is the side the right-angled triangle is built on","Use it as the hypotenuse in that right-angled triangle, with the nearer angle of elevation, to reach the distance along the ground"]},
  "quadratics.parabola-y-intercept": {"skill":"Read a and b off a turning point, then find where the curve cuts the y-axis","method":"State a, state b, then find c by putting x = 0 into the equation","moves":["Read the turning point's \\(x\\)-coordinate off the graph — the bracket is zero there, so that coordinate is \\(-a\\), and the sign flips when you write \\(a\\) down","Take \\(b\\) from the turning point's \\(y\\)-coordinate, because the bracket adds nothing where it is zero","Put \\(x = 0\\) into the equation you have now built, to find where the curve cuts the \\(y\\)-axis"]},
  "trig-graphs.shift-and-raise": {"skill":"Separate a sideways shift from a vertical one on a trig graph","method":"State a from the sideways shift, then b from how far the whole wave has been lifted","moves":["Find the \\(x\\) value of the marked peak. An unshifted \\(\\cos\\) graph peaks at \\(x = 0\\), so how far along the axis this one peaks tells you the sideways slide, and sliding right puts a minus sign inside the bracket","Now read the top and bottom values off the \\(y\\)-axis. The lift does not change how tall the wave is, it moves the line the wave is balanced about — a plain \\(\\cos\\) graph is balanced about \\(0\\), so how far this one's middle has risen gives the other letter"]},
  "inequalities.fractions": {"skill":"Multiply through by the lowest common multiple, then solve","method":"Eliminate the denominators, then rearrange into ax > b, then solve","moves":["Work out the smallest number all the bottom lines divide into, then multiply each term on both sides by it so the fractions clear away","Multiply out any bracket this leaves you with, then gather the \\(x\\) terms on one side and the plain numbers on the other","Divide both sides by the number in front of \\(x\\), flipping the inequality sign round if that number is negative, and give the answer as a range of values rather than a single one"]},
  "percentages.two-stage": {"skill":"One rate for the first year, a different rate for the years after","method":"Know how to decrease by both rates, then know how to calculate the value, then evaluate","moves":["Turn each of the two percentage changes into its own multiplier","Multiply the starting amount by the first multiplier once, then by the second one raised to the number of years it covers","Work it out, rounding to whatever accuracy the question asks for"]},
  "sci-notation.calculate-3sf": {"skill":"As above, then round the answer to three significant figures","method":"Correct method, then evaluate, then express in scientific notation rounded to three significant figures","moves":["Decide from the wording whether the quantities are multiplied or one is divided by the other, turning any percentage into a decimal multiplier, and write that calculation down with the powers of ten kept in","Run the whole calculation through your calculator in one pass, using the \\(\\times 10^{n}\\) button, and hold on to the full display rather than rounding at this stage","Write the result in scientific notation with the front number between \\(1\\) and \\(10\\), then round that front number to three significant figures"]},
  "angles.bar-polygon": {"skill":"A right angle plus the exterior angle of a regular polygon","method":"Interior or exterior angle of the polygon, then the shaded angle","moves":["Divide 360 by the number of sides of the polygon to get the turn from one side to the next at each corner","Add that turn onto the \\(90^{\\circ}\\) where the crossbar meets the upright, because the shaded angle is those two parts together"]},
  "volume.pyramid-minus-pyramid": {"skill":"Subtract a similar pyramid from a pyramid, finding the large height first","method":"Small pyramid, large pyramid, know to subtract, calculate with units","moves":["Work out the small pyramid with \\(V = \\frac{1}{3}Ah\\), squaring its base length to get \\(A\\)","Add the two parts of the height to find how tall the large pyramid stood before the tip came off, then use the same formula with its own base","What is left behind is the large pyramid with the small one gone, so take the small volume away from the large","Carry out that subtraction and write the answer with its cubic units"]},
  "form-equation.cuboid": {"skill":"Turn a cuboid volume into a quadratic, then solve it","method":"Write the volume expression and rearrange it into a quadratic, then substitute into the quadratic formula and solve","moves":["Multiply the length, the breadth and the height of the store together to build an expression for its volume","Set that expression equal to the volume given in the question, expand it, and take every term to one side so the quadratic is equal to 0","Read \\(a\\), \\(b\\) and \\(c\\) straight off that quadratic, put them into the quadratic formula, and work out \\(b^{2} - 4ac\\) underneath the square root sign","Take the square root and work the fraction out twice, once with the plus and once with the minus, then reject the negative value because a breadth cannot be negative, and round what is left to the accuracy the question asks for"]},
  "composite.split-side-area": {"skill":"Sine from the small triangle, then the area formula run backwards","method":"Find the sine from the small right-angled triangle, put it into the area of a triangle formula, set that equal to the area you are given, then solve for the length","moves":["Take the perpendicular over the hypotenuse in the small right-angled triangle to get \\(\\sin\\) of the angle the two triangles share, and keep it as a fraction rather than rounding it","Add the pieces along the arm to get the full side of the large triangle, then put that side, the unknown side and your fraction into \\(\\frac{1}{2}ab\\sin C\\)","Set that expression equal to the area you are given, since the area is what pins the unknown length down","Rearrange the equation to leave the unknown length on its own"]},
  "surds.subtract": {"skill":"Simplify each surd to a common root, then subtract the coefficients","method":"Simplify the surds so they share a root, then complete the simplification by combining the coefficients","moves":["Take the largest square factor out of each root in turn, so that both surds end up sitting on the same root","With the roots now matching, subtract the second coefficient from the first and keep that shared root beside it"]},
  "angles.two-tangents-diameters": {"skill":"Angle at the centre twice the angle at the circumference, then a quadrilateral with two right angles","method":"Angle OFD, then BOD as twice it, then BCD","moves":["Take the angle you are given off 180, because the diameter carries straight on through that point and the angles along it add to 180","Double that angle, since an angle at the centre is twice the angle at the circumference standing on the same arc","Close the quadrilateral formed by the two tangents and the two radii drawn to their points of contact: its angles add to 360 and both radius-to-tangent corners are \\(90^{\\circ}\\)"]},
  "quadratics.turning-point-related": {"skill":"Complete the square, read the turning point, then reflect a point in the axis of symmetry","method":"The bracket and the completed square, then the turning point, then the x and the y of Q","moves":["Halve the coefficient of \\(x\\) for the bracket, then take off what squaring that bracket adds on and bring the constant down beside it","Read the turning point straight off the completed square — the bracket is at its smallest when it is zero, and the number left outside is the height there","Put \\(x = 0\\) to find the point on the \\(y\\)-axis, then step the same distance to the other side of the turning point, because a parabola is symmetrical about it","Give the second point the same \\(y\\)-coordinate as the first, since the line joining them is horizontal"]},
  "indices.expand": {"skill":"Expand a bracket whose terms carry fractional and negative indices","method":"Apply one of the two multiplications, then apply both and simplify","moves":["Multiply the term outside by the first term inside, adding their powers as usual, since a power that is a fraction or a minus still just adds on","Do the same with the second term in the bracket, then write the two results as a sum, using \\(a^{0} = 1\\) if a power cancels away to nothing"]},
  "similarity.triangle-rest": {"skill":"The linear scale factor applied to a whole side, then what is left","method":"Scale factor, scale the whole side consistently, then subtract","moves":["The two triangles are similar, so write the linear scale factor as the short parallel side over the long parallel side","Multiply the full length of the sloping side by that scale factor, which gives you the part of it belonging to the small triangle","Subtract that part from the full length, because the piece you have been asked for is what is left over"]},
  "volume.box-minus-hemisphere": {"skill":"Subtract a hemisphere from a cuboid","method":"Hemisphere, cuboid and subtract, calculate, round","moves":["Halve the hemisphere's diameter for its radius, then take half of \\(\\frac{4}{3}\\pi r^{3}\\)","Multiply the cuboid's height by its two base lengths to get the volume of the whole block","The part being asked about is the block with the hemisphere scooped out, so subtract the hemisphere's volume from the cuboid's","Carry out the subtraction on the unrounded figures, then round as asked and state the cubic units"]},
  "composite.perpendicular-in-triangle": {"skill":"Sine rule for a slant side, then the right angle at the foot","method":"Substitute into the sine rule and rearrange it to get the slant side, then use that side in the right-angled triangle to reach the perpendicular","moves":["Take the two marked angles away from 180 to fill in the third angle of the whole triangle","Pair each side with the angle facing it in the sine rule to reach the slanted side running from the top vertex down to the given base, then rearrange and work its length out — the perpendicular cannot be found without it","Use that slanted side as the hypotenuse of the small right-angled triangle formed by the perpendicular, with the angle at the base vertex, to reach the perpendicular"]},
  "vectors.pathway-rhombus": {"skill":"Use a diagonal and a midpoint to cross a rhombus","method":"Get the side from the diagonal first, then take the pathway through the midpoint and collect it","moves":["Cross from one corner to the next by reversing the side you are given and then running along the diagonal of the rhombus","Add on half of the side the midpoint lies on, which is a copy of the side you were given, pointing the other way","Collect the terms so each letter appears once in the pathway"]},
  "sector.area-arc": {"skill":"The arc gives the angle, and the angle gives the area","method":"Work back from the arc to find what fraction of the circle it is, turn that fraction into the angle, then use the angle in the sector area formula","moves":["Divide the arc by the whole circumference, \\(\\pi\\) times the diameter, to find what fraction of the circle the sector covers","Turn that fraction into the area — either as that fraction of the whole circle's area, or as half the arc times the radius","Work the area out, rounding as the question asks"]},
  "trig-identities.given-form": {"skill":"Substitute \\(\\cos^2 x = 1 - \\sin^2 x\\), then collect terms into the given form","method":"Substitute \\(\\cos^2 x = 1 - \\sin^2 x\\), then collect the terms into the form the question asks for","moves":["Compare what you have with the form printed in the question and spot which function has to disappear. Rearranging \\(\\sin^{2} x^{\\circ} + \\cos^{2} x^{\\circ} = 1\\) gives you the swap that removes it, such as \\(\\cos^{2} x^{\\circ} = 1 - \\sin^{2} x^{\\circ}\\)","Substitute that in, multiply out the bracket, then gather the plain numbers together so what is left has the same shape as the form asked for"]},
  "straight-line.from-marked-points": {"skill":"Find the equation of a line from two points marked on a sketch","method":"Find the gradient from the two marked points, substitute it and one point into \\(y = mx + c\\), then tidy the equation up","moves":["Read the coordinates of both marked points off the sketch, then divide the change in \\(y\\) by the change in \\(x\\) to get the gradient","Put the gradient and either one of the points into \\(y = mx + c\\), leaving \\(c\\) as the only unknown","Rearrange for \\(c\\) and write the equation out with \\(y\\) on its own and the numbers collected together"]},
  "functions.evaluate-then-solve": {"skill":"Evaluate f at a value, then solve f(a) = b for a","method":"Substitute the value into the function for part (a); for part (b) set the function equal to the number given and solve for the unknown","moves":["For the first part, put the number from the brackets in place of every \\(x\\) and work the arithmetic through to one number","For the second part, write the formula out again with the unknown letter in place of \\(x\\) and put it equal to the number given on the right","Take the number that is added on across to the other side, then divide both sides by the number in front of the letter"]},
  "quadratics.parabola-from-turning-point": {"skill":"Read a and b off a turning point, watching the sign of a","method":"Read a off the turning point and settle its sign before going on, then read b","moves":["Read the turning point's \\(x\\)-coordinate off the graph — the bracket is zero there, so that coordinate is \\(-a\\), and the sign flips when you write \\(a\\) down","Take \\(b\\) from the height of the turning point, because the bracket contributes nothing where it is zero"]},
  "indices.laws": {"skill":"Apply the power, multiplication and division laws in one expression","method":"Apply the power of a power, then multiply by adding the powers, then divide by subtracting them","moves":["Start with the bracket, multiplying the two powers together, since \\((a^{m})^{n} = a^{mn}\\)","Multiply the terms on the top by adding their powers","Divide by subtracting the power underneath from the power above it"]},
  "vectors.draw-resultant": {"skill":"Add two vectors in components and draw the resultant on a grid","method":"The components of p+q (or a nose-to-tail diagram), then the resultant drawn consistently","moves":["Add the two given vectors one component at a time, across with across and up with up","Draw a single arrow that moves by those components, starting anywhere on the grid, and put an arrowhead on it to show the direction"]},
  "form-equation.rectangle-square": {"skill":"Equate two areas, factorise, and reject the root that is not a length","method":"Write the area, expand and rearrange it, then factorise, solve, and reject the negative root","moves":["Multiply the length of the rectangle by its breadth and leave the answer as a pair of brackets for the moment","Get the area of the square by multiplying its side by itself, set the two areas equal, expand both sides and take every term to one side so the quadratic is equal to 0","Factorise that quadratic into two brackets, then set each bracket equal to 0 to get the two values of \\(x\\)","Throw away the negative value because a side of a shape cannot be a negative length, then feed the one that survives back into the rectangle's length and breadth expressions to get its two measurements"]},
  "sector.area-angle": {"skill":"Radius and angle to the area of the sector","method":"Write the angle as a fraction of 360, substitute the radius into the sector area formula, then work the area out","moves":["Write the angle over 360 — that fraction is how much of the whole circle the sector takes up","Multiply that fraction by the area of the whole circle, \\(\\pi\\) times the radius squared","Work the area out, rounding to the accuracy the question asks for"]},
  "pythagoras.coordinates-cuboid": {"skill":"Read a vertex off a cuboid on axes, then find a space diagonal","method":"Read the coordinates of the vertex off the axes, use Pythagoras across the base of the cuboid, then use it again with the height to reach the space diagonal","moves":["Write the missing corner's coordinates down, taking each one from whichever labelled vertex of the cuboid already shows it","Square the three coordinates of that corner, since the line runs out from the origin","Add the three squares together to get the square of the diagonal","Take the square root to get the length of that diagonal"]},
  "similarity.area-scale": {"skill":"Square the linear scale factor to scale an area","method":"Find the linear scale factor, multiply or divide the area by its square, then find the area","moves":["Write the linear scale factor as the length on the figure you want over the matching length on the figure you are given, so it scales in the right direction","Square that scale factor, because an area is two-dimensional and scales by the square of the linear one, then multiply the area you are given by it","Work that out, and write the square units beside your answer"]},
  "bearings.two-sides": {"skill":"Sine rule for the angle, then turn it back into a bearing","method":"Substitute into the sine rule, rearrange to make the sine the subject, take the inverse to get the angle, then measure it from north to give a bearing","moves":["Draw a north line where the bearing is given and subtract to turn it into the angle inside the triangle, then pair each known side with the angle facing it and write the sine rule with the sines on top","Rearrange so the sine of the unknown angle is on its own, and work that number out","Press inverse sine to turn it into an angle, then take it and the angle you started with off \\(180\\) to reach the angle at the corner the bearing is asked from","Work out the bearing back along the side you already know, turn through that angle in the direction the diagram shows, and give a three-figure bearing measured clockwise from north"]},
  "vectors.pathway-running-on": {"skill":"Continue past a point by a fraction of the line already travelled","method":"The base as a sum and the fraction of it beyond the end, then the route from the third point","moves":["Add the two lettered vectors nose to tail to get the whole line, then take the fraction of it that the piece running on past the end is worth","Build the pathway from the point you are asked about: travel to the end of that line, then on along the fraction beyond it, and gather the terms"]},
  "fractions.context": {"skill":"Read the operation from a worded situation and answer with units","method":"Decide from the words which operation it is, put both fractions over a common denominator, then work it out and give the answer with its units","moves":["Pull the two amounts out of the words and write each one as a top-heavy fraction over a bottom line they share","Look at whether the question wants the two amounts brought together or one taken away from the other, carry that out on the numerators, then write the answer as a mixed number with the units it is measured in"]},
  "vectors.magnitude-surd": {"skill":"Find a magnitude that does not come out whole, and simplify it","method":"Square and add, take the root, simplify the surd","moves":["Square each component and add the squares to get the number that will sit under the root","Write the magnitude as the square root of that total, leaving the root in place for now","Split the number under the root into its largest square factor times what is left, then bring the root of that square factor outside"]},
  "change-subject.root-two-step": {"skill":"Square both sides, then move the one remaining term","method":"Square both sides to clear the root, then add the remaining term to the other side","moves":["Undo the square root by squaring each side, which frees the subject from underneath it","Add the term that is being taken away from the subject onto both sides, leaving the subject on its own"]},
  "angles.tangent-reflex": {"skill":"Two isosceles triangles from the radii, one reached through the right angle at a tangent","method":"Two isosceles triangles from the radii, one reached through the right angle at the tangent, then their sum","moves":["Start on the side where a base angle is given: the two radii make that triangle isosceles, so double the angle and take it off 180 for its angle at the centre","On the other side, subtract the second given angle from the \\(90^{\\circ}\\) between the radius and the tangent, then run the same isosceles working for that triangle's angle at the centre","Add the two centre angles, as they lie on opposite sides of the radius and together sweep out the reflex angle"]},
  "coords.lettered-cuboid": {"skill":"Read coordinates off a fully lettered cuboid, and find a midpoint on one edge","method":"State G, then state the midpoint of CD","moves":["Work out from the vertices that already carry coordinates which direction along the cuboid each of \\(x\\), \\(y\\) and \\(z\\) runs","Build the vertex you are asked for one coordinate at a time, taking each from whichever labelled vertex lies in line with it, and using 0 for any coordinate sitting on the floor or a wall","For the midpoint, average the coordinates that change between the two ends of that edge and copy across the ones that stay the same"]},
  "functions.evaluate-trig": {"skill":"Evaluate a trigonometric function at a quadrantal angle","method":"Substitute the value and work out the angle inside, then apply the exact value and multiply","moves":["Replace \\(x\\) with the number in the brackets, then work out the angle sitting inside the \\(\\sin\\) or \\(\\cos\\) before you touch anything else","Use the exact value of that ratio at the angle you have ended up with, then multiply it by the number in front"]},
  "factorising.solve-non-unitary": {"skill":"Factorise a quadratic whose x squared term has a coefficient, then solve","method":"Split the leading coefficient, complete the factorisation, then solve","moves":["Start from the \\(x^{2}\\) term: pick a pair of factors of its coefficient and open two brackets with those sitting in front of the \\(x\\)","Fill the second slot in each bracket with a pair of factors of the constant, then multiply the outsides and the insides and swap the pairing around until they add to the middle term","A product is 0 only when one of its factors is 0, so set each bracket to 0 in turn and solve each one for \\(x\\)"]},
  "simeq.construct-combine": {"skill":"Solve a constructed pair, then use both values on a new quantity","method":"1 + 1 + 4 as the question data gives, mapping onto the other five papers exactly except that the last mark applies the two values rather than stating them","moves":["Give each of the two unknown amounts a letter and say what it stands for, then turn the first sentence into an equation: how many of each, multiplied by its letter, adding up to the total that sentence gives","Do the same with the second sentence, so you have two equations sharing the same two letters","Multiply one equation right through so one letter matches in both, add or subtract to cancel it, then put what comes out back in to get the other letter","Go back to what the final part actually asks for, multiply each letter's amount by how many of that item it wants, add the two together and give the answer in its units"]},
  "pythagoras.chord-radius": {"skill":"Use the bisected chord and Pythagoras to find the radius","method":"Halve the chord, state Pythagoras with the radius as the hypotenuse, then evaluate and take the root","moves":["Halve the chord, since the perpendicular from the centre meets it at its midpoint","Write Pythagoras down with half the chord and the distance from the centre as the two short sides, and the radius as the hypotenuse","Add those two squares, then take the square root to get the radius"]},
  "volume.sphere-cone-equal": {"skill":"Find the height of a cone with the same volume as a given sphere","method":"Work out the sphere's volume first, then substitute it into the volume of a cone and solve for the height","moves":["Substitute the sphere's radius into \\(V = \\frac{4}{3}\\pi r^{3}\\) and work out its volume","Halve the cone's base diameter for its radius, then put that and an unknown height into \\(\\frac{1}{3}\\pi r^{2}h\\) and set it equal to the volume you just found","Rearrange to leave \\(h\\) on its own, then work the height out to the accuracy the question asks for"]},
  "alg-fractions.divide-squares-on-top": {"skill":"Divide algebraic fractions where the numerator factorises","method":"Start to divide by taking the reciprocal, factorise the difference of two squares, then cancel and state","moves":["Flip the second fraction upside down and multiply by it, since dividing by a fraction is multiplying by its reciprocal","Factorise the numerator: it is a difference of two squares, so it splits into two brackets","Cancel the bracket that now sits above and below the line, then multiply the numbers that are left"]},
  "sector.polygon-segment": {"skill":"Equal vertices give the angle at the centre, then sector less triangle","method":"The angle from the number of vertices, express the sector as a fraction of the circle, evaluate it, the triangle, then subtract","moves":["Count the vertices, then divide 360 by that count — they sit equally spaced round the circle, so that gives the angle at the centre","Write that angle over 360 and multiply by the whole circle's area, \\(\\pi\\) times the radius squared, to get one sector","Find the triangle at the centre with \\(\\frac{1}{2}ab\\sin C\\), two radii with that angle between them","Take the triangle from the sector to leave the shaded segment, and state the units with your answer"]},
  "indices.coefficient-quotient": {"skill":"Take a power into a bracket in a denominator, then divide","method":"Take the power to both parts of the denominator, divide the powers of the variable, then assemble the answer over the coefficient","moves":["Raise both parts inside the bottom bracket to the outside power, so the number at the front gets it too, not just the letter","Subtract the power of the letter underneath from the power of the letter above it","The number underneath has nothing to cancel with, so write your simplified letter over it"]},
  "form-equation.three-sided": {"skill":"A wall on three sides grows the length twice and the width once","method":"The 1 + 2 + 4 the question data gives, split as 2015 P2 Q14 splits its identical parts","moves":["Trace round the plan and mark which sides have a wall against them, since only those sides push the measurement outwards — count how many times \\(x\\) gets added to each dimension, then write an expression for each","Multiply those two expressions together and expand them for the area of the base, then set that equal to the area you are given and take every term to one side so the quadratic is equal to 0","Read \\(a\\), \\(b\\) and \\(c\\) straight off that quadratic, put them into the quadratic formula, and work out \\(b^{2} - 4ac\\) underneath the square root sign","Take the square root and work the fraction out twice, once with the plus and once with the minus, then reject the negative value because a wall cannot be a negative thickness, and round what is left to the accuracy the question asks for"]},
};

